from collections import Counter
from typing import List

def suffixPairs(words: List[str]) -> int:
    cnt = Counter(words)
    ans = 0
    # 相等的两两成对
    for c in cnt.values():
        ans += c * (c - 1) // 2
    # 不相等：短串是长串的真后缀。每个长串枚举它的所有真后缀（长度 <= 10）
    for w, c in cnt.items():
        for k in range(1, len(w)):
            s = w[k:]
            if s in cnt:
                ans += c * cnt[s]
    return ans
